let cart = [], mode = 'sale', toastTimer, searchTimer, customerTimer, selectedCustomer = null, searchSequence = 0, activeMatchIndex = -1, checkoutBusy = false;
const $ = id => document.getElementById(id);
const money = value => Number(value || 0).toLocaleString('es-MX', {minimumFractionDigits:2, maximumFractionDigits:2});
const safeText = value => String(value ?? '');
const products = Array.isArray(INITIAL_PRODUCTS) ? INITIAL_PRODUCTS : [];

async function apiGet(url) { const response = await fetch(url, {headers:{'X-Requested-With':'XMLHttpRequest'}}); if (!response.ok) throw new Error('No se pudo consultar el servidor.'); return response.json(); }
async function apiPost(url, data) { const response = await fetch(url, {method:'POST', body:new URLSearchParams(data), headers:{'X-Requested-With':'XMLHttpRequest'}}); if (!response.ok) throw new Error('No se pudo completar la operación.'); return response.json(); }
function showToast(message, error=false) { const toast=$('toast'); toast.textContent=message; toast.classList.toggle('error',error); toast.hidden=false; clearTimeout(toastTimer); toastTimer=setTimeout(()=>toast.hidden=true,3600); $('status').textContent=message; $('status').className='pos-status '+(error?'error':'ok'); }
function setMode(next) { mode=next; $('modeSale').classList.toggle('active',mode==='sale'); $('modePrice').classList.toggle('active',mode==='price'); $('scanner').placeholder=mode==='price'?'Escanea o busca para consultar precio y existencia…':'Escanea o escribe el nombre del producto…'; $('scanner').focus(); }
function lineAmount(item) { return item.total_etiqueta != null ? Number(item.total_etiqueta) : Number(item.cantidad)*Number(item.precio_unitario); }
function addProduct(product, qty=1, scannedPrice=null, barcode=null) {
    if (!product || Number(qty)<=0) return;
    const weighed=Boolean(product.etiqueta_peso || barcode);
    const existing=!weighed && cart.find(row=>Number(row.id_producto)===Number(product.id_producto));
    if (existing) existing.cantidad=Number(existing.cantidad)+Number(qty);
    else cart.push({id_producto:Number(product.id_producto),nombre:safeText(product.nombre),cantidad:Number(qty),precio_unitario:Number(product.precio),departamento:product.departamento||'ABARROTES',unidad:product.unidad_base||'PZA',codigo_escaneado:barcode,total_etiqueta:barcode?Number(scannedPrice):null,stock:product.stock,etiqueta_peso:weighed});
    renderCart(); $('scanner').value=''; $('matches').replaceChildren(); $('priceResult').hidden=true; $('scanner').focus();
}
function renderCart() {
    const tbody=$('cartRows'); tbody.replaceChildren();
    cart.forEach((item,index)=>{
        const row=document.createElement('tr');
        const name=document.createElement('td'); name.innerHTML=''; const strong=document.createElement('span'); strong.className='pos-item-name'; strong.textContent=item.nombre; const meta=document.createElement('small'); meta.className='pos-item-meta'; meta.textContent=(item.departamento||'ABARROTES')+' · '+item.unidad+(item.etiqueta_peso?' · Etiqueta de báscula':''); name.append(strong,meta);
        const quantity=document.createElement('td'); const input=document.createElement('input'); input.className='pos-qty'; input.type='number'; input.min='.001'; input.step=String(item.unidad).toUpperCase()==='KG'?'.001':'1'; input.value=item.cantidad; input.setAttribute('aria-label','Cantidad de '+item.nombre); input.disabled=Boolean(item.codigo_escaneado); input.addEventListener('change',()=>{const value=Number(input.value);if(value<=0){cart.splice(index,1)}else{item.cantidad=value;item.total_etiqueta=null;item.codigo_escaneado=null;item.etiqueta_peso=false}renderCart()}); quantity.append(input);
        const price=document.createElement('td'); price.className='pos-unit-price'; price.textContent='$'+money(item.precio_unitario)+' / '+item.unidad;
        const subtotal=document.createElement('td'); subtotal.className='pos-line-total'; subtotal.textContent='$'+money(lineAmount(item));
        const remove=document.createElement('td'); const button=document.createElement('button'); button.type='button'; button.className='pos-remove'; button.innerHTML='<i class="fa-solid fa-trash-can"></i>'; button.setAttribute('aria-label','Quitar '+item.nombre); button.addEventListener('click',()=>{cart.splice(index,1);renderCart()}); remove.append(button);
        row.append(name,quantity,price,subtotal,remove); tbody.append(row);
    });
    const total=cart.reduce((sum,item)=>sum+lineAmount(item),0), qty=cart.reduce((sum,item)=>sum+Number(item.cantidad),0);
    $('cartEmpty').hidden=cart.length>0; $('cartTableWrap').hidden=cart.length===0; $('itemCount').textContent=String(cart.length); $('cartSummary').textContent=cart.length+' '+(cart.length===1?'artículo':'artículos')+' · '+qty.toLocaleString('es-MX',{maximumFractionDigits:3})+' unidades'; $('total').textContent=money(total); $('payTotal').textContent=money(total); updatePaymentSummary();
}
async function handleScan(value, isBarcode=false, commitSingle=false) {
    const query=value.trim(); if(!query)return; const requestSequence=++searchSequence;
    try {
        const data=await apiGet(BASE+'admin/pos/buscar?'+(isBarcode?'codigo':'q')+'='+encodeURIComponent(query));
        if(requestSequence!==searchSequence)return;
        const matches=data.productos||[];
        if(isBarcode && matches.length===1) {
            const product=matches[0];
            if(mode==='price'){showPrice(product);$('scanner').value='';$('matches').replaceChildren();return}
            if(product.etiqueta_peso){addProduct(product,product.cantidad_venta||1,product.precio_etiqueta,query);return}
            openProductOptions(product); return;
        }
        if(mode==='price' && matches.length===1){showPrice(matches[0]);return}
        if(mode==='sale' && commitSingle && matches.length===1){openProductOptions(matches[0]);return}
        showMatches(matches);
        if(!matches.length && isBarcode && mode==='sale') openQuickProduct(query);
        else if((isBarcode||commitSingle)&&!matches.length) showToast('No encontramos ese producto. Revisa el código o prueba con otra búsqueda.',true);
    } catch(error) { showToast(error.message||'No se pudo buscar el producto.',true); }
}
function showMatches(matches) {
    const container=$('matches');container.replaceChildren();activeMatchIndex=-1;
    matches.slice(0,10).forEach((product,index)=>{const button=document.createElement('button');button.type='button';button.className='pos-match';button.setAttribute('role','option');button.setAttribute('aria-selected','false');const left=document.createElement('span');const name=document.createElement('strong');name.textContent=product.nombre;const detail=document.createElement('small');detail.textContent=(product.departamento||'ABARROTES')+' · Existencia '+(product.stock??'sin control')+' '+(product.unidad_base||'PZA');left.append(name,detail);const price=document.createElement('strong');price.textContent='$'+money(product.precio)+' / '+(product.unidad_base||'PZA');button.append(left,price);button.addEventListener('click',()=>{if(mode==='price'){showPrice(product);container.replaceChildren()}else openProductOptions(product)});button.addEventListener('mouseenter',()=>setActiveMatch(index));container.append(button)});
}
function openQuickProduct(barcode){
    const form=modalForm([
        {id:'quickBarcode',label:'Código de barras',value:barcode,required:true},
        {id:'quickName',label:'Nombre del producto',required:true},
        {id:'quickPrice',label:'Precio de venta',type:'number',min:'.01',step:'.01',placeholder:'0.00',required:true},
        {id:'quickDepartment',label:'Departamento',type:'select',options:[{value:'ABARROTES',label:'Abarrotes'},{value:'VERDULERIA',label:'Verdulería'}]},
        {id:'quickUnit',label:'Unidad de venta',type:'select',options:[{value:'PZA',label:'Pieza'},{value:'KG',label:'Kilogramo'},{value:'G',label:'Gramo'},{value:'L',label:'Litro'}]},
        {id:'quickStock',label:'Existencia inicial',type:'number',min:'0',step:'.001',value:'1',required:true},
        {id:'quickCategory',label:'Categoría (opcional)'},
        {id:'quickDescription',label:'Descripción (opcional)'}
    ],'Registrar y agregar',async values=>{
        try{
            const result=await apiPost(BASE+'admin/pos/producto-rapido',{
                codigo_barras:values.quickBarcode,nombre:values.quickName,precio:values.quickPrice,
                departamento:values.quickDepartment,unidad_base:values.quickUnit,stock:values.quickStock,
                categoria:values.quickCategory,descripcion:values.quickDescription
            });
            if(!result.respuesta)throw new Error(result.mensaje);
            products.push(result.producto);
            closeTool();
            addProduct(result.producto);
            showToast('Producto registrado y agregado a la cuenta.');
        }catch(error){showToast(error.message||'No se pudo registrar el producto.',true)}
    });
    setModal('Producto no encontrado · alta rápida',form);
}
function setActiveMatch(index){const options=[...$('matches').querySelectorAll('.pos-match')];if(!options.length)return;activeMatchIndex=Math.max(0,Math.min(index,options.length-1));options.forEach((option,i)=>{option.classList.toggle('active',i===activeMatchIndex);option.setAttribute('aria-selected',String(i===activeMatchIndex))});options[activeMatchIndex].scrollIntoView({block:'nearest'});}
function showPrice(product) { $('priceResult').replaceChildren(); const info=document.createElement('div');info.className='pos-price-product';info.textContent=product.nombre;const meta=document.createElement('small');meta.textContent=(product.departamento||'ABARROTES')+' · '+(product.unidad_base||'PZA')+(product.etiqueta_peso?' · Etiqueta: '+Number(product.cantidad_venta).toLocaleString('es-MX',{maximumFractionDigits:3})+' '+(product.unidad_base||'kg'):'');info.append(meta);const price=document.createElement('strong');price.className='pos-price-amount';price.textContent='$'+money(product.etiqueta_peso?product.precio_etiqueta:product.precio);const stock=document.createElement('small');stock.className='pos-price-stock';stock.textContent=(product.etiqueta_peso?'Importe de la etiqueta · precio unitario $'+money(product.precio)+' / '+(product.unidad_base||'kg')+' · ':'')+'Existencia: '+(product.stock??'sin control')+' '+(product.unidad_base||'PZA');price.append(stock);$('priceResult').append(info,price);$('priceResult').hidden=false; }
 $('scanner').addEventListener('keydown',event=>{const options=$('matches').querySelectorAll('.pos-match');if(event.key==='ArrowDown'&&options.length){event.preventDefault();setActiveMatch(activeMatchIndex+1);return}if(event.key==='ArrowUp'&&options.length){event.preventDefault();setActiveMatch(activeMatchIndex<0?options.length-1:activeMatchIndex-1);return}if(event.key==='Enter'){event.preventDefault();clearTimeout(searchTimer);const value=$('scanner').value.trim();const numericCode=/^\d{8,14}$/.test(value);if(!numericCode&&activeMatchIndex>=0&&options[activeMatchIndex]){options[activeMatchIndex].click();return}if(numericCode){$('matches').replaceChildren();activeMatchIndex=-1}handleScan(value,numericCode,true)}if(event.key==='Escape')$('matches').replaceChildren()});
$('scanner').addEventListener('input',event=>{clearTimeout(searchTimer);activeMatchIndex=-1;$('priceResult').hidden=true;if(event.target.value.trim().length<1){$('matches').replaceChildren();return}searchTimer=setTimeout(()=>handleScan(event.target.value,false),150)});
function updatePaymentSummary(){const total=cart.reduce((sum,item)=>sum+lineAmount(item),0), method=$('payment').value, received=Number($('received').value||0);$('payTotal').textContent=money(total);$('changeDue').textContent=money(Math.max(0,received-total));const mix=Number($('mixCash').value||0)+Number($('mixTransfer').value||0)+Number($('mixCard').value||0);$('mixRemaining').textContent=mix>=total?'Listo':('$'+money(total-mix));$('mixRemaining').style.color=mix>total+.01?'#c2473e':'#27364a';$('receivedWrap').hidden=['MIXTO','CREDITO'].includes(method)||method!=='EFECTIVO';$('mixedWrap').hidden=method!=='MIXTO';$('creditNote').hidden=method!=='CREDITO';$('chargeButton').innerHTML=method==='CREDITO'?'<i class="fa-solid fa-book"></i> Cargar a cuenta':'<i class="fa-solid fa-check"></i> Cobrar venta';}
$('payment').addEventListener('change',()=>{if(['TRANSFERENCIA','TARJETA'].includes($('payment').value))$('received').value=$('total').textContent;updatePaymentSummary()});['received','mixCash','mixTransfer','mixCard'].forEach(id=>$(id).addEventListener('input',updatePaymentSummary));
function setCustomer(customer){selectedCustomer=customer;$('customerId').value=customer.id_cliente;$('customerSearch').value='';$('customerResults').hidden=true;$('selectedCustomerName').textContent=customer.nombre_completo+' · '+customer.telefono;$('selectedCustomer').hidden=false;}
function clearCustomer() {selectedCustomer=null;$('customerId').value='';$('selectedCustomer').hidden=true;$('customerSearch').value='';$('customerSearch').focus();}
$('customerSearch').addEventListener('input',()=>{clearTimeout(customerTimer);const q=$('customerSearch').value.trim();if(q.length<2){$('customerResults').hidden=true;return}customerTimer=setTimeout(async()=>{try{const data=await apiGet(BASE+'admin/clientes/buscarJson?q='+encodeURIComponent(q));const results=$('customerResults');results.replaceChildren();(data.data||[]).filter(c=>c.estatus==='ACTIVO').slice(0,8).forEach(customer=>{const button=document.createElement('button');button.type='button';button.className='pos-customer-option';const name=document.createElement('strong');name.textContent=customer.nombre_completo;const detail=document.createElement('small');detail.textContent=(customer.telefono||'Sin teléfono')+' · Crédito disponible $'+money(customer.credito_disponible);button.append(name,detail);button.addEventListener('click',()=>setCustomer(customer));results.append(button)});if(!results.childElementCount){const empty=document.createElement('div');empty.className='pos-customer-option';empty.textContent='No encontramos clientes activos.';results.append(empty)}results.hidden=false}catch(error){showToast(error.message,true)}},220)});
document.addEventListener('click',event=>{if(!event.target.closest('.pos-customer-wrap'))$('customerResults').hidden=true});
function setModal(title, content){$('modalTitle').textContent=title;$('modalBody').replaceChildren();if(typeof content==='string')$('modalBody').innerHTML=content;else $('modalBody').append(content);$('modal').classList.add('open');const first=$('modalBody').querySelector('input,select,button');if(first)setTimeout(()=>first.focus(),30)}
function closeTool(){$('modal').classList.remove('open');$('scanner').focus()}
function modalForm(fields, submitText, onSubmit){const form=document.createElement('form');form.className='pos-dialog-form';fields.forEach(field=>{const label=document.createElement('label');label.className='pos-label';label.textContent=field.label;let input;if(field.type==='select'){input=document.createElement('select');input.className='pos-field';field.options.forEach(option=>{const opt=document.createElement('option');opt.value=option.value;opt.textContent=option.label;input.append(opt)})}else{input=document.createElement('input');input.className='pos-field';input.type=field.type||'text';input.placeholder=field.placeholder||'';input.step=field.step||'';input.min=field.min||'';input.value=field.value||'';input.required=Boolean(field.required)}input.id=field.id;label.htmlFor=field.id;form.append(label,input)});const actions=document.createElement('div');actions.className='pos-dialog-actions';const cancel=document.createElement('button');cancel.type='button';cancel.className='btn btn-secondary';cancel.textContent='Cancelar';cancel.addEventListener('click',closeTool);const submit=document.createElement('button');submit.type='submit';submit.className='btn btn-primary';submit.textContent=submitText;actions.append(cancel,submit);form.append(actions);form.addEventListener('submit',event=>{event.preventDefault();onSubmit(Object.fromEntries(fields.map(field=>[field.id,$(field.id).value])))});return form}
function getProducts(){return products}
function openVeg(){const list=document.createElement('div');list.className='pos-product-grid';const vegetables=getProducts().filter(product=>product.departamento==='VERDULERIA');if(!vegetables.length){list.textContent='No hay productos marcados como verdulería.'}vegetables.forEach(product=>{const tile=document.createElement('button');tile.type='button';tile.className='pos-product-tile';const icon=document.createElement('i');icon.className='fa-solid fa-carrot';const name=document.createElement('strong');name.textContent=product.nombre;const detail=document.createElement('span');detail.textContent='$'+money(product.precio)+' / '+(product.unidad_base||'kg')+' · Existencia '+(product.stock??'—');tile.append(icon,name,detail);tile.addEventListener('click',()=>chooseVegetable(product));list.append(tile)});setModal('Verdulería · venta rápida',list)}
function openProductOptions(product, defaultQty=1){
    const unit=product.unidad_base||'PZA', isKg=unit.toUpperCase()==='KG';
    const form=document.createElement('form');form.className='pos-dialog-form';
    const info=document.createElement('p');info.className='pos-credit-note';info.textContent=product.nombre+' · $'+money(product.precio)+' por '+unit+' · Existencia: '+(product.stock??'sin control')+' '+unit;form.append(info);
    let modeSelect=null;
    if(isKg){
        const label=document.createElement('label');label.className='pos-label';label.htmlFor='productEntryMode';label.textContent='¿Cómo quieres indicar la venta?';
        modeSelect=document.createElement('select');modeSelect.id='productEntryMode';modeSelect.className='pos-field';
        [['quantity','Por peso (kg)'],['amount','Por importe ($)']].forEach(([value,text])=>{const option=document.createElement('option');option.value=value;option.textContent=text;modeSelect.append(option)});
        form.append(label,modeSelect);
    }
    const qtyLabel=document.createElement('label');qtyLabel.className='pos-label';qtyLabel.htmlFor='productEntryQty';qtyLabel.textContent='Cantidad ('+unit+')';
    const qty=document.createElement('input');qty.id='productEntryQty';qty.className='pos-field large';qty.type='number';qty.min=isKg?'.001':'1';qty.step=isKg?'.001':'1';qty.value=String(defaultQty);qty.required=true;
    const amountLabel=document.createElement('label');amountLabel.className='pos-label';amountLabel.htmlFor='productEntryAmount';amountLabel.textContent='Importe a cobrar ($)';amountLabel.hidden=true;
    const amount=document.createElement('input');amount.id='productEntryAmount';amount.className='pos-field large';amount.type='number';amount.min='.01';amount.step='.01';amount.value=money(Number(defaultQty)*Number(product.precio)).replace(/,/g,'');amount.hidden=true;
    const calculated=document.createElement('div');calculated.className='pos-change';calculated.style.margin='10px 0 14px';
    const calculatedLabel=document.createElement('span');calculatedLabel.textContent='Total estimado';const calculatedValue=document.createElement('strong');calculated.append(calculatedLabel,calculatedValue);
    const actions=document.createElement('div');actions.className='pos-dialog-actions';const cancel=document.createElement('button');cancel.type='button';cancel.className='btn btn-secondary';cancel.textContent='Cancelar';cancel.addEventListener('click',closeTool);const submit=document.createElement('button');submit.type='submit';submit.className='btn btn-primary';submit.textContent='Agregar a la cuenta';actions.append(cancel,submit);
    form.append(qtyLabel,qty,amountLabel,amount,calculated,actions);
    const update=()=>{const amountMode=modeSelect&&modeSelect.value==='amount';qtyLabel.hidden=amountMode;qty.hidden=amountMode;amountLabel.hidden=!amountMode;amount.hidden=!amountMode;const q=amountMode?Math.round((Number(amount.value)/Number(product.precio))*1000)/1000:Number(qty.value);calculatedValue.textContent='$'+money(q*Number(product.precio))+(amountMode&&q>0?' · '+q.toLocaleString('es-MX',{maximumFractionDigits:3})+' '+unit:'');};
    qty.addEventListener('input',update);amount.addEventListener('input',update);if(modeSelect)modeSelect.addEventListener('change',update);update();
    form.addEventListener('submit',event=>{event.preventDefault();const amountMode=modeSelect&&modeSelect.value==='amount';const q=amountMode?Math.round((Number(amount.value)/Number(product.precio))*1000)/1000:Number(qty.value);if(!Number.isFinite(q)||q<=0)return showToast('Indica una cantidad o importe mayor que cero.',true);addProduct(product,q);closeTool()});
    setModal(product.nombre,form);
}
function chooseVegetable(product){openProductOptions(product,product.unidad_base==='KG' ? 0.500 : 1)}
function pauseSale(){if(!cart.length)return showToast('Agrega al menos un producto antes de pausar.',true);const form=modalForm([{id:'holdReference',label:'Referencia para reconocer la cuenta',placeholder:'Nombre del cliente (opcional)'}],'Pausar venta',async values=>{try{const data=await apiPost(BASE+'admin/pos/pausar',{items:JSON.stringify(cart),referencia:values.holdReference});if(!data.respuesta)throw new Error(data.mensaje);cart=[];renderCart();closeTool();showToast(data.mensaje)}catch(error){showToast(error.message,true)}});setModal('Poner cuenta en espera',form)}
async function showHolds(){try{const data=await apiGet(BASE+'admin/pos/esperas');const list=document.createElement('div');list.className='pos-hold-list';(data.esperas||[]).forEach(hold=>{const row=document.createElement('div');row.className='pos-hold-row';const info=document.createElement('div');const title=document.createElement('strong');title.textContent=(hold.referencia||'Cuenta sin referencia')+' · #'+hold.id_espera;const detail=document.createElement('small');detail.textContent=new Date(hold.fecha_creacion).toLocaleString('es-MX');info.append(title,detail);const actions=document.createElement('div');actions.style.display='flex';actions.style.gap='6px';const restore=document.createElement('button');restore.type='button';restore.className='btn btn-primary btn-sm';restore.textContent='Retomar';restore.addEventListener('click',async()=>{try{if(cart.length&&!confirm('Al retomar, la cuenta actual se reemplazará. ¿Continuar?'))return;const result=await apiPost(BASE+'admin/pos/esperas/'+hold.id_espera+'/recuperar',{});if(!result.respuesta)throw new Error(result.mensaje);cart=result.items||[];renderCart();closeTool();showToast('Cuenta recuperada.')}catch(error){showToast(error.message,true)}});const remove=document.createElement('button');remove.type='button';remove.className='btn btn-secondary btn-sm';remove.innerHTML='<i class="fa-solid fa-trash"></i>';remove.title='Eliminar cuenta en espera';remove.addEventListener('click',async()=>{if(!confirm('¿Eliminar esta cuenta en espera?'))return;try{await apiPost(BASE+'admin/pos/esperas/'+hold.id_espera+'/eliminar',{});showHolds()}catch(error){showToast(error.message,true)}});actions.append(restore,remove);row.append(info,actions);list.append(row)});if(!list.childElementCount)list.textContent='No hay cuentas en espera.';setModal('Cuentas en espera',list)}catch(error){showToast(error.message,true)}}
function productOptions(){return getProducts().map(product=>({value:product.id_producto,label:product.nombre+' · '+(product.unidad_base||'PZA')}))}
function openTool(type){
    if(type==='entry'){const form=modalForm([{id:'entryProduct',label:'Producto',type:'select',options:productOptions()},{id:'packs',label:'Cantidad de empaques',type:'number',min:'.001',step:'.001',placeholder:'Ej. 1 costal o caja'},{id:'units',label:'Unidades base por empaque',type:'number',min:'.001',step:'.001',placeholder:'Ej. 20 kg o 24 piezas'}],'Registrar entrada',values=>submitTool('entrada',{id_producto:values.entryProduct,empaques:values.packs,unidades_por_empaque:values.units}));setModal('Entrada de mercancía',form)}
    else if(type==='merma'){const form=modalForm([{id:'wasteProduct',label:'Producto',type:'select',options:productOptions()},{id:'wasteQty',label:'Cantidad de merma',type:'number',min:'.001',step:'.001',placeholder:'Ej. 1.500 kg'},{id:'wasteReason',label:'Motivo',placeholder:'Maduró, daño, caducidad…',required:true}],'Registrar merma',values=>submitTool('merma',{id_producto:values.wasteProduct,cantidad:values.wasteQty,motivo:values.wasteReason}));setModal('Merma de inventario',form)}
    else if(type==='customer'){const form=modalForm([{id:'newName',label:'Nombre completo',required:true},{id:'newPhone',label:'Teléfono',required:true},{id:'newLimit',label:'Límite de crédito autorizado',type:'number',min:'0',step:'.01',value:'0',required:true}],'Crear cliente',async values=>{try{const result=await apiPost(BASE+'admin/pos/cliente',{nombre_completo:values.newName,telefono:values.newPhone,limite_credito:values.newLimit});if(!result.respuesta)throw new Error(result.mensaje);setCustomer({id_cliente:result.id_cliente,nombre_completo:values.newName,telefono:values.newPhone});closeTool();showToast('Cliente registrado y seleccionado.')}catch(error){showToast(error.message,true)}});setModal('Alta rápida de cliente',form)}
    else if(type==='payment'){
        let selectedPayCustomer=null;
        const form=modalForm([{id:'paySearch',label:'Buscar cliente por nombre o teléfono',placeholder:'Escribe al menos 2 caracteres',required:true},{id:'payAmount',label:'Monto del abono',type:'number',min:'.01',step:'.01',required:true},{id:'payMethod',label:'Forma de pago',type:'select',options:[{value:'EFECTIVO',label:'Efectivo'},{value:'TRANSFERENCIA',label:'Transferencia'},{value:'TARJETA',label:'Tarjeta'}]}],'Registrar abono',async values=>{
            try{
                if(!selectedPayCustomer)throw new Error('Busca y selecciona al cliente antes de registrar el abono.');
                const customer=selectedPayCustomer;
                const result=await apiPost(BASE+'admin/pos/abono',{id_cliente:customer.id_cliente,monto:values.payAmount,metodo_pago:values.payMethod});
                if(!result.respuesta)throw new Error(result.mensaje);
                const receipt=document.createElement('div');receipt.className='pos-receipt';receipt.innerHTML='<h3>Comprobante de abono</h3><p>Cliente: '+escapeHtml(customer.nombre_completo)+'</p><p>Fecha: '+new Date().toLocaleString('es-MX')+'</p><div class="pos-result-grid"><div class="pos-result-card"><small>Saldo anterior</small><strong>$'+money(result.saldo_anterior)+'</strong></div><div class="pos-result-card"><small>Abono recibido</small><strong>$'+money(result.monto)+'</strong></div></div><div class="pos-receipt-total"><span>Nuevo saldo</span><span>$'+money(result.saldo_nuevo)+'</span></div><div class="pos-dialog-actions"><button type="button" class="btn btn-secondary" onclick="closeTool()">Cerrar</button><button type="button" class="btn btn-primary" onclick="window.print()"><i class="fa-solid fa-print"></i> Imprimir</button></div>';
                setModal('Abono registrado',receipt);showToast('Abono registrado correctamente.');
            }catch(error){showToast(error.message,true)}
        });
        const search=form.querySelector('#paySearch'), picker=document.createElement('div'), results=document.createElement('div');picker.className='pos-customer-wrap';results.className='pos-customer-results';results.hidden=true;search.parentNode.insertBefore(picker,search);picker.append(search,results);let timer;
        search.addEventListener('input',()=>{selectedPayCustomer=null;clearTimeout(timer);const query=search.value.trim();if(query.length<2){results.hidden=true;return}timer=setTimeout(async()=>{try{const data=await apiGet(BASE+'admin/clientes/buscarJson?q='+encodeURIComponent(query));results.replaceChildren();(data.data||[]).filter(customer=>customer.estatus==='ACTIVO').slice(0,8).forEach(customer=>{const option=document.createElement('button');option.type='button';option.className='pos-customer-option';const name=document.createElement('strong');name.textContent=customer.nombre_completo;const detail=document.createElement('small');detail.textContent=(customer.telefono||'Sin teléfono')+' · Saldo $'+money(customer.saldo_actual);option.append(name,detail);option.addEventListener('click',()=>{selectedPayCustomer=customer;search.value=customer.nombre_completo+' · '+customer.telefono;results.hidden=true});results.append(option)});if(!results.childElementCount){const none=document.createElement('div');none.className='pos-customer-option';none.textContent='No hay clientes activos con esa búsqueda.';results.append(none)}results.hidden=false}catch(error){showToast(error.message,true)}},220)});
        setModal('Registrar abono a cuenta',form);$('paySearch').focus();
    }
    else if(type==='cut')openCut();
}
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
async function submitTool(endpoint,body){try{const result=await apiPost(BASE+'admin/pos/'+endpoint,body);if(!result.respuesta)throw new Error(result.mensaje);closeTool();showToast(result.mensaje)}catch(error){showToast(error.message,true)}}
function openCut(){const form=modalForm([{id:'cashCounted',label:'Efectivo físico contado en caja',type:'number',min:'0',step:'.01',placeholder:'Captura el monto contado',required:true}],'Ver corte del día',async values=>{try{const result=await apiPost(BASE+'admin/pos/corte',{efectivo_contado:values.cashCounted});if(!result.respuesta)throw new Error(result.mensaje);const report=document.createElement('div');report.innerHTML='<p>El corte corresponde a las ventas registradas hoy.</p><div class="pos-result-grid"><div class="pos-result-card"><small>Total vendido</small><strong>$'+money(result.total)+'</strong></div><div class="pos-result-card"><small>Efectivo esperado</small><strong>$'+money(result.efectivo_esperado)+'</strong></div><div class="pos-result-card"><small>Efectivo contado</small><strong>$'+money(result.efectivo_contado)+'</strong></div><div class="pos-result-card"><small>Diferencia</small><strong>$'+money(result.diferencia)+'</strong></div><div class="pos-result-card"><small>Abarrotes</small><strong>$'+money(result.abarrotes)+'</strong></div><div class="pos-result-card"><small>Verdulería</small><strong>$'+money(result.verduleria)+'</strong></div></div><h3 style="font-size:12px;margin:16px 0 8px">Desglose por forma de pago</h3><div class="pos-hold-list">'+(result.pagos||[]).map(payment=>'<div class="pos-hold-row"><strong>'+escapeHtml(payment.metodo)+'</strong><strong>$'+money(payment.monto)+'</strong></div>').join('')+'</div><div class="pos-dialog-actions"><button type="button" class="btn btn-primary" onclick="closeTool()">Listo</button></div>';setModal('Corte de caja · '+new Date().toLocaleDateString('es-MX'),report);showToast('Corte registrado.')}catch(error){showToast(error.message,true)}});setModal('Corte ciego · cuenta el efectivo primero',form)}
async function checkout(){
    if(checkoutBusy)return;
    if(!cart.length)return showToast('La cuenta está vacía.',true);
    const total=cart.reduce((sum,item)=>sum+lineAmount(item),0), method=$('payment').value, clientId=$('customerId').value;
    if(method==='CREDITO'&&!clientId)return showToast('Busca y selecciona el cliente que llevará la compra a cuenta.',true);
    let received=$('received').value||total, payments=[];
    if(method==='TRANSFERENCIA'||method==='TARJETA')received=total;
    if(method==='MIXTO'){payments=[['EFECTIVO',$('mixCash').value],['TRANSFERENCIA',$('mixTransfer').value],['TARJETA',$('mixCard').value]].filter(([,amount])=>Number(amount)>0).map(([metodo,monto])=>({metodo,monto:Number(monto)}));if(Math.abs(payments.reduce((sum,payment)=>sum+payment.monto,0)-total)>.01)return showToast('Los pagos combinados deben sumar exactamente $'+money(total)+'.',true)}
    if(method==='EFECTIVO'&&Number(received)<total)return showToast('El efectivo recibido no cubre el total.',true);
    checkoutBusy=true;$('chargeButton').disabled=true;
    const quiereImprimir=$('printTicketChoice').checked;
    const ticketWindow=quiereImprimir?window.open('','ticket','width=380,height=700'):null;
    try{
        const result=await apiPost(BASE+'admin/pos/cobrar',{items:JSON.stringify(cart),metodo_pago:method,recibido:received,id_cliente:clientId,pagos:JSON.stringify(payments)});
        if(!result.respuesta){if(ticketWindow)ticketWindow.close();throw new Error(result.mensaje)}
        const snapshot=cart.map(item=>({...item}));if(quiereImprimir&&ticketWindow)printTicket(ticketWindow,result.id_venta,snapshot,total,method,received);cart=[];renderCart();$('received').value='';['mixCash','mixTransfer','mixCard'].forEach(id=>$(id).value='');updatePaymentSummary();showToast(result.mensaje);const saved=document.createElement('div');saved.innerHTML='<div class="pos-result-grid"><div class="pos-result-card"><small>Folio guardado</small><strong>#'+escapeHtml(result.id_venta)+'</strong></div><div class="pos-result-card"><small>Total registrado</small><strong>$'+money(total)+'</strong></div><div class="pos-result-card"><small>Forma de pago</small><strong>'+escapeHtml(method)+'</strong></div></div><p>La venta quedó registrada y ya aparece en el historial de ventas.</p>'+(quiereImprimir&&!ticketWindow?'<p class="form-mensaje error">El navegador bloqueó la ventana de impresión. Puedes reimprimirla desde Ventas.</p>':'')+'<div class="pos-dialog-actions"><a class="btn btn-secondary" href="'+BASE+'admin/ventas">Ver historial</a><button type="button" class="btn btn-primary" onclick="closeTool()">Nueva venta</button></div>';setModal('Venta guardada',saved);$('scanner').focus();
    }catch(error){if(ticketWindow&&!ticketWindow.closed)ticketWindow.close();showToast(error.message||'No se pudo registrar la venta.',true)}finally{checkoutBusy=false;$('chargeButton').disabled=false}
}
function printTicket(win,id,items,total,method,received){if(!win)return;const rows=items.map(item=>'<tr><td>'+escapeHtml(item.nombre)+'<br><small>'+Number(item.cantidad).toLocaleString('es-MX',{maximumFractionDigits:3})+' '+escapeHtml(item.unidad)+'</small></td><td style="text-align:right">$'+money(lineAmount(item))+'</td></tr>').join('');win.document.write('<!doctype html><html lang="es"><meta charset="utf-8"><title>Ticket '+id+'</title><style>body{font:12px Arial,sans-serif;padding:16px;color:#222}h2,p{text-align:center}table{width:100%;border-collapse:collapse}td{padding:7px 0;border-bottom:1px dashed #bbb}small{color:#666}.total{font-size:18px;font-weight:bold;border-top:1px solid #333;padding-top:12px} @media print{button{display:none}}</style><body><h2>Tienda y Abarrotes</h2><p>Ticket #'+id+'<br>'+new Date().toLocaleString('es-MX')+'</p><table>'+rows+'</table><p class="total">Total: $'+money(total)+'</p><p>Forma de pago: '+escapeHtml(method)+'</p>'+(method==='EFECTIVO'?'<p>Recibido: $'+money(received)+' · Cambio: $'+money(Math.max(0,Number(received)-total))+'</p>':'')+'<p>¡Gracias por su compra!</p><script>window.onload=()=>window.print()<\/script></body></html>');win.document.close()}
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&$('modal').classList.contains('open'))closeTool();if(event.key==='F2'){event.preventDefault();$('scanner').focus()}if(event.key==='F3'){event.preventDefault();openVeg()}if(event.key==='F4'){event.preventDefault();setMode(mode==='price'?'sale':'price')}if(event.key==='F8'){event.preventDefault();checkout()}});
renderCart();$('scanner').focus();
</script>
